<?php
/** Real competing processes and observed InnoDB waiters; no sleeps pretending to prove contention. */
require_once __DIR__.'/issuers_core_support.php';require_once APPPATH.'services/InvoicePaymentWriter.php';require_once APP_MODULES_PATH.'banco_brasil/libraries/BancoBrasil/ReviewedTariffReceipt.php';
if(!str_starts_with(getenv('ISSUERS_TEST_DSN')?:'','mysql:'))exit(2);
function tariffRaceDb(string $p):EssentialTestDb{return new EssentialTestDb(new PDO(getenv('ISSUERS_TEST_DSN'),getenv('ISSUERS_TEST_USER'),getenv('ISSUERS_TEST_PASSWORD')),$p);}
if(($argv[1]??'')==='worker'){$p=$argv[2]??'';if(!preg_match('/^essential_[a-f0-9]{10}_$/D',$p))exit(2);$v=json_decode(stream_get_contents(STDIN),true,16,JSON_THROW_ON_ERROR);$db=tariffRaceDb($p);$GLOBALS['essentialPrefix']=$p;try{$payment=(new \app\services\InvoicePaymentWriter($db))->recordCompanyProviderReceipt($v['issuer'],15,new \BancoBrasil\ReviewedTariffReceipt($v['event'],$v['proof']));echo json_encode(['ok'=>true,'payment'=>$payment],JSON_THROW_ON_ERROR);}catch(Throwable $e){echo json_encode(['ok'=>false,'class'=>get_class($e),'error'=>$e->getMessage()],JSON_THROW_ON_ERROR);}exit(0);}
require __DIR__.'/banco_brasil_tariff_mysql.php';
$db->query("INSERT INTO {$p}issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,15,'banco_brasil','reconcile_tariff')",[$a]);$observer=tariffRaceDb($p);$blocker=(int)$db->query('SELECT CONNECTION_ID() id')->row()->id;
function tariffRace(array $events,?callable $beforeRelease=null):array
{
    global $db,$p,$a,$proof,$observer,$blocker;
    $db->trans_begin();$db->query("SELECT id FROM {$p}issuers_lock WHERE id=1 FOR UPDATE");$workers=[];
    try{foreach($events as$event){$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,'worker',$p],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($proc))throw new RuntimeException('tariff worker unavailable');fwrite($pipes[0],json_encode(['issuer'=>$a,'event'=>$event,'proof'=>$proof],JSON_THROW_ON_ERROR));fclose($pipes[0]);$workers[]=[$proc,$pipes];}$deadline=microtime(true)+20;do{$waiters=essentialLockWaiters($observer,$blocker);if($waiters>=2)break;usleep(20000);}while(microtime(true)<$deadline);essentialCheck($waiters>=2,'Both independent tariff workers actually wait on the canonical installation lock');if($beforeRelease)$beforeRelease();$db->trans_commit();$outputs=[];foreach($workers as[$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);essentialCheck($exit===0&&$err==='','Worker exits without PHP diagnostics');$outputs[]=json_decode($out,true,16,JSON_THROW_ON_ERROR);}return$outputs;}
    finally{if($db->pdo->inTransaction())$db->trans_rollback();}
}
$results=[];
foreach(['same_event','competing_full_credits','revoked_tariff','disabled_actor','connection_changed','source_corrupt']as$mode){$db->query("INSERT IGNORE INTO {$p}issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,15,'banco_brasil','reconcile_tariff')",[$a]);$db->query("UPDATE {$p}staff SET active=1 WHERE staffid=15");$db->query("UPDATE {$p}bb_connections SET configuration_hash=? WHERE id=?",[$connectionRow['configuration_hash'],$connection]);$invoice=freshTariffOrigin('race-'.$mode);$event=importTariffCredit();$reconcile->link($a,7,$event);$events=[$event,$event];if($mode==='competing_full_credits'){$other=importTariffCredit(['fee'=>'3.53','net'=>'102.00']);$reconcile->link($a,7,$other);$events=[$event,$other];}
 $release=match($mode){'revoked_tariff'=>fn()=>$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=? AND staff_id=15 AND feature='banco_brasil' AND capability='reconcile_tariff'",[$a]),'disabled_actor'=>fn()=>$db->query("UPDATE {$p}staff SET active=0 WHERE staffid=15"),'connection_changed'=>fn()=>$db->query("UPDATE {$p}bb_connections SET configuration_hash=? WHERE id=?",[str_repeat('0',64),$connection]),'source_corrupt'=>fn()=>$db->query("UPDATE {$p}bb_return_events SET payload_hash=? WHERE id=?",[str_repeat('0',64),$event]),default=>null};$out=tariffRace($events,$release);$wins=array_values(array_filter($out,fn($v)=>$v['ok']));$loss=array_values(array_filter($out,fn($v)=>!$v['ok']));$count=(int)$db->query("SELECT COUNT(*) n FROM {$p}invoicepaymentrecords WHERE invoiceid=?",[$invoice])->row()->n;
 if($mode==='same_event'){essentialCheck(count($wins)===2&&$wins[0]['payment']===$wins[1]['payment']&&$count===1,'Two same-event workers receive the same single canonical payment');}
 elseif($mode==='competing_full_credits'){essentialCheck(count($wins)===1&&count($loss)===1&&$count===1&&$loss[0]['class']==='DomainException'&&$loss[0]['error']==='company_bank_tariff_full_nominal_required','Two distinct full credits cannot both extinguish one nominal debt');}
 else{essentialCheck($wins===[]&&count($loss)===2&&$count===0,'A current authority/source change while waiting vetoes both writers');foreach($loss as$v)essentialCheck($v['class']==='DomainException'&&!in_array($v['error'],['issuer_storage_failed','company_payment_invalid_input'],true),'Concurrency denial is a business guard, not a bootstrap/storage failure');}
 essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}company_bank_receipt_components WHERE invoice_id=?",[$invoice])->row()->n===$count,'Race leaves exactly one component proof per actual native receipt');$results[$mode]=['two_waiters_observed'=>true,'outputs'=>$out,'payments'=>$count];
}
if(($file=getenv('BB_TARIFF_RACE_RESULTS'))!==false)file_put_contents($file,json_encode($results,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));
echo 'BB240 tariff concurrency: six scenarios, two observed independent waiters each; '.$GLOBALS['essentialChecks'].' cumulative checks.'.PHP_EOL;
